WITH scored AS (SELECT *, AVG(stock_qty) OVER w_running AS stock_qty_avg_3, SUM(stock_qty) OVER w_ordered AS cumulative_stock_qty FROM products WHERE launch_date BETWEEN '2023-12-01' AND '2025-03-01' WINDOW w_running AS (PARTITION BY category ORDER BY price, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW), w_ordered AS (ORDER BY price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT id, product_name, brand, price, cost, stock_qty, launch_date, supplier_id, stock_qty_avg_3 FROM scored;
